new file mode 100644
index 0000000..dc0f9db
--- /dev/null
+++ b/migrations/0003_rename_users_email.sql
@@ -0,0 +1,20 @@
+ALTER TABLE users ADD COLUMN email_address TEXT;
+DO $$
+DECLARE
+  batch_size INT := 1000;
+  min_id BIGINT;
+  max_id BIGINT;
+  cur_id BIGINT;
+BEGIN
+  SELECT MIN(id), MAX(id) INTO min_id, max_id FROM users;
+  IF min_id IS NOT NULL THEN
+    cur_id := min_id;
+    WHILE cur_id <= max_id LOOP
+      UPDATE users
+      SET email_address = email
+      WHERE id >= cur_id AND id < cur_id + batch_size
+        AND email_address IS NULL;
+      cur_id := cur_id + batch_size;
+    END LOOP;
+  END IF;
+END $$;

