diff --git a/migrations/0003_rename_users_email_to_email_address.sql b/migrations/0003_rename_users_email_to_email_address.sql
new file mode 100644
index 0000000..74f2c28
--- /dev/null
+++ b/migrations/0003_rename_users_email_to_email_address.sql
@@ -0,0 +1,50 @@
+ALTER TABLE users ADD COLUMN email_address TEXT;
+
+CREATE OR REPLACE FUNCTION sync_users_email_address()
+RETURNS TRIGGER AS $$
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    IF NEW.email IS NOT NULL AND NEW.email_address IS NULL THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email_address IS NOT NULL AND NEW.email IS NULL THEN
+      NEW.email := NEW.email_address;
+    ELSIF NEW.email IS NOT NULL AND NEW.email_address IS NOT NULL AND NEW.email <> NEW.email_address THEN
+      NEW.email_address := NEW.email;
+    END IF;
+  ELSIF TG_OP = 'UPDATE' THEN
+    IF NEW.email IS DISTINCT FROM OLD.email THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email_address IS DISTINCT FROM OLD.email_address THEN
+      NEW.email := NEW.email_address;
+    END IF;
+  END IF;
+  RETURN NEW;
+END;
+$$ LANGUAGE plpgsql;
+
+CREATE TRIGGER sync_users_email_address_trigger
+BEFORE INSERT OR UPDATE ON users
+FOR EACH ROW
+EXECUTE FUNCTION sync_users_email_address();
+
+DO $$
+DECLARE
+  rows_updated INT;
+BEGIN
+  LOOP
+    UPDATE users
+    SET email_address = email
+    WHERE id IN (
+      SELECT id FROM users
+      WHERE email_address IS NULL
+      LIMIT 1000
+    );
+    GET DIAGNOSTICS rows_updated = ROW_COUNT;
+    EXIT WHEN rows_updated = 0;
+    COMMIT;
+  END LOOP;
+END $$;
+
+COMMIT;
+
+CREATE UNIQUE INDEX CONCURRENTLY users_email_address_key ON users (email_address);

